package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveEscalateAfter {
    public void save(@Val EscalateAfter days, @Val Sheet sheet, SettingRepository repository) {
        if (days.given()) {
            repository.saveEscalateAfter(sheet.id(), days.value());
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the escalation gap just saved (blank: off), even when it is the one the sheet had; nothing when left as it is. */
public class AuditEscalateAfter {
    public void audit(@Val EscalateAfter days, @Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        if (!days.given()) {
            return;
        }
        audit.record("SETTING_CHANGED sheet=" + sheet.id() + " by=" + user + " key=escalate-after value="
                + (days.value() == null ? "" : days.value().toString()));
    }
}
package net.officefloor.hq.app.setting;

/** A validated escalation gap, whole days; {@code value} null: blank, off. {@code given} false: left as it is. */
public record EscalateAfter(boolean given, Integer value) {
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.Size;
import java.util.Map;

/**
 * The settings as the form submits them; a setting left out (null) is left as it is. The clerk limit has two
 * decimals at most (blank: no limit); the floor has two decimals at most (blank: back to 1.00); the terms are
 * whole days, 0 or more (blank: back to 14); the late percent has two decimals at most (blank: back to 0.00); the policy date is
 * yyyy-MM-dd (blank: the sheet's today); the period numbering from date is yyyy-MM-dd (blank: off); the entry date is yyyy-MM-dd (blank: off); the cap has two decimals at most (blank: no cap); the proof threshold has two decimals at most (blank: none); the note threshold has two decimals at most (blank: none); the review threshold has two decimals at most (blank: none). The grade terms are
 * whole days, 0 or more, by grade, each only for a grade it carries (blank: none of its own, the sheet's terms).
 * The clerk limit, floor, terms, late percent, cap, proof threshold, note threshold, review threshold and each grade's terms are recorded from their from-date, yyyy-MM-dd
 * (left out or blank: the sheet's today). The permissions are, by action (open, settle, void, reassign, close, reopen),
 * the roles allowed it, comma separated (blank: the standing rule); they are not dated. The grace days are whole days,
 * 0 or more (blank: off); they are not dated. The grade grace days are whole days, 0 or more, by grade, each only for a
 * grade it carries (blank: none), recorded from their from-date by grade (left out or blank: the sheet's today). The pot has two decimals at most (blank: none); it is not dated. The parent is a sheet id (blank: none); it is not dated. The fiscal start month is 1 to 12 (blank: back to 1); it is not dated. The alert threshold has two decimals at most (blank: off); it is not dated. The grade
 * proof thresholds have two decimals at most, by grade, each only for a grade it carries (blank: none, the sheet's), recorded
 * from their from-date by grade (left out or blank: the sheet's today). The rounding mode is half-up or half-even (blank: none,
 * the policy date decides), recorded from its from-date (left out or blank: the sheet's today). The escalation gap is whole
 * days, 0 or more (blank: off); it is not dated. The review SLA is whole days, 0 or more (blank: none); it is not dated.
 * The proof kinds are receipt or photo, comma separated (blank: none); they are not dated.
 * The score thresholds (mid, high) are whole numbers (blank: none); they are not dated.
 * The score log is "on" or blank; it is not dated.
 * The default grade is A, B or C (blank: A); it is not dated.
 * The grade clerk limits have two decimals at most, by grade, each only for a grade it carries (blank: none, the sheet's),
 * recorded from their from-date by grade (left out or blank: the sheet's today).
 */
public record SettingsRequest(@Size(max = 30) String clerkLimit, @Size(max = 30) String floor, @Size(max = 30) String terms,
        @Size(max = 30) String latePct, @Size(max = 30) String policyDate, @Size(max = 30) String periodNumberingFrom, @Size(max = 30) String entryDate, @Size(max = 30) String cap,
        @Size(max = 30) String proofThreshold, @Size(max = 30) String noteThreshold, @Size(max = 30) String reviewThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTerms,
        @Size(max = 30) String clerkLimitFrom, @Size(max = 30) String floorFrom, @Size(max = 30) String termsFrom,
        @Size(max = 30) String latePctFrom, @Size(max = 30) String capFrom, @Size(max = 30) String proofThresholdFrom,
        @Size(max = 30) String noteThresholdFrom, @Size(max = 30) String reviewThresholdFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTermsFrom,
        @Size(max = 10) Map<String, @Size(max = 100) String> permissions, @Size(max = 30) String graceDays,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGrace,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGraceFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThresholdFrom,
        @Size(max = 30) String pot, @Size(max = 100) String parent, @Size(max = 30) String fiscalStartMonth,
        @Size(max = 30) String alertThreshold, @Size(max = 30) String rounding, @Size(max = 30) String roundingFrom,
        @Size(max = 30) String escalateAfter, @Size(max = 30) String reviewSla, @Size(max = 100) String proofKinds,
        @Size(max = 10) String defaultGrade,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeClerkLimit,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeClerkLimitFrom,
        @Size(max = 30) String scoreMid, @Size(max = 30) String scoreHigh, @Size(max = 30) String scoreLog) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;

/**
 * A sheet's settings: its clerk limit (null: no limit), its floor (a claim's live due is at least it), its terms
 * (a claim is due by its date plus this many days), the terms set for each grade that has its own (by grade; any
 * other grade uses the sheet's terms), its late percent (an overdue claim gains it of its figure
 * every full 30 days), its rounding policy date (null: blank, the sheet's
 * today), its period numbering from date (null: off; on or after it, an opened claim is numbered within its period)
 * its entry date (null: off; a new claim left without a date takes it instead of the sheet's today)
 * its cap (null: none; a person's due-total is at most it), its proof threshold (null: none; a claim whose due is above
 * the one in force on its date is settled or approved only once it has a proof) the roles given to user names (any other name is a clerk) and its
 * permission matrix (the roles allowed each of open, settle, void, reassign, close and reopen) and its grace days (null: off;
 * when its today is changed, an open period whose to-date plus them is before the new today is closed).
 * The clerk limit, floor, terms, grade terms, late percent, cap and proof threshold are those in force on the sheet's today; {@code dated}
 * holds every value recorded for them, by from-date. {@code delegations} are the steward role delegated to user names, in the
 * order made; one in force on {@code today} (the sheet's today) makes its user act as a steward in every rule.
 * {@code pot} is the sheet's pot (null: none), the pot of each pool that is a member of no pool, shared out among its members when it is balanced; it is not dated.
 * {@code parent} is the sheet's parent sheet id (null: none), whose rates a grade with none of its own in force takes; it is not dated.
 * {@code fiscalStartMonth} is the month (1 to 12) each of the sheet's fiscal years starts in; it is not dated.
 * {@code escalateAfter} is the sheet's escalation gap in days (null: off): reminding a claim whose previous reminder was at least
 * that many days before today escalates it (once per claim); it is not dated.
 * {@code reviewSla} is the sheet's review SLA in days (null: none): a REVIEW claim whose review day (the sheet's today when it
 * went to REVIEW) plus it is before today is late; it is not dated.
 * {@code proofKinds} are the sheet's proof kinds (empty: none): while set, a claim whose due is above the proof threshold in force on
 * its date is settled or approved only once it has a proof of each; they are not dated.
 * {@code defaultGrade} is the sheet's default grade (null: blank, A), the grade a quick-added person and an imported line with a
 * blank grade take; it is not dated.
 * {@code scoreMid} and {@code scoreHigh} are the sheet's score thresholds, whole numbers (null: blank): while both are set,
 * each person shows a band; they are not dated.
 * {@code scoreLog} is the sheet's score log switch (false: blank): while on, changing the sheet's today records each
 * person's score as it stood on the day being left; it is not dated.
 * {@code alertThreshold} is the sheet's alert threshold (null: off), above which a person's due-total crossing is alerted in the audit; it is not dated.
 */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, Map<String, Integer> gradeTerms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, LocalDate entryDate, BigDecimal cap, BigDecimal proofThreshold, List<UserRole> roles, DatedSettings dated, Permissions permissions, Integer graceDays,
        LocalDate today, List<Delegation> delegations, BigDecimal pot, String parent, int fiscalStartMonth, BigDecimal alertThreshold,
        Integer escalateAfter, Integer reviewSla, List<String> proofKinds, String defaultGrade, Integer scoreMid, Integer scoreHigh,
        boolean scoreLog) {

    /** The role the user name acts in: steward while a delegation to it is in force on today, else its given role. */
    public Role roleOf(String user) {
        return delegatorOf(user) != null ? Role.STEWARD : givenRoleOf(user);
    }

    /** The role given to the user name, else clerk (a delegation aside). */
    public Role givenRoleOf(String user) {
        return roles.stream().filter((r) -> r.user().equals(user)).map(UserRole::role).findFirst().orElse(Role.CLERK);
    }

    /** The steward who delegated the role to the user name by the latest delegation in force on today, else null. */
    public String delegatorOf(String user) {
        String by = null;
        for (Delegation d : delegations) {
            if (d.user().equals(user) && d.covers(today)) {
                by = d.by();
            }
        }
        return by;
    }

    /** Whether the user's role is allowed the action (open, settle, void, reassign, close or reopen) by the permission matrix. */
    public boolean may(String user, String action) {
        return permissions.allows(action, roleOf(user));
    }

    /**
     * Whether the user may settle a claim of a person of the grade (null: none) with this due (null: n/a, within any
     * limit): the limit is the grade's own clerk limit in force on today, when it has one, else the sheet's.
     */
    public boolean maySettle(String user, String grade, BigDecimal due) {
        BigDecimal limit = dated.clerkLimitFor(grade, today);
        return roleOf(user) == Role.STEWARD || limit == null || due == null || due.compareTo(limit) <= 0;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The settings as the screen reads them: the clerk limit (null: no limit), the floor, the terms in days, the terms set for
 * each grade that has its own (by grade), the late percent, the policy date ("": blank, the sheet's today), the period
 * numbering from date ("": off), the entry date ("": off), the cap ("": none), the proof threshold ("": none), the note threshold ("": none), the review threshold ("": none) — the dated ones as in force on the sheet's today — each role given,
 * by user name, the permission matrix (by action, the roles allowed it; "": blank, the standing rule), and every dated value recorded, by key, oldest from-date first (value "": blank), the grace days ("": off), the steward role delegated, in the order made, the pot ("": none), the parent sheet id ("": none) the fiscal year start month (1 to 12), the alert threshold ("": off) the rounding mode in force on the sheet's today ("": none) and the escalation gap in days ("": off) and the review SLA in days ("": none) and the proof kinds, comma separated ("": none) and the default grade ("": blank, A) and the mid and high score thresholds ("": blank) and the score log ("on"; "": blank).
 */
public record SettingsResponse(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms, String latePct, String policyDate, String periodNumberingFrom, String entryDate, String cap, String proofThreshold, String noteThreshold, String reviewThreshold, List<RoleResponse> roles,
        Map<String, List<FromValueResponse>> history, Map<String, String> permissions, String graceDays,
        List<DelegationResponse> delegations, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding,
        String escalateAfter, String reviewSla, String proofKinds, String defaultGrade, String scoreMid, String scoreHigh,
        String scoreLog) {

    public record RoleResponse(String user, String role) {
    }

    public record DelegationResponse(String user, String from, String to, String by) {
    }

    public record FromValueResponse(String from, String value) {
    }

    public static SettingsResponse from(Settings settings) {
        BigDecimal noteThreshold = settings.dated().noteThresholdOn(settings.today());
        BigDecimal reviewThreshold = settings.dated().reviewThresholdOn(settings.today());
        String rounding = settings.dated().roundingOn(settings.today());
        Map<String, List<FromValueResponse>> history = new LinkedHashMap<>();
        settings.dated().history().forEach((key, values) -> history.put(key, values.stream()
                .map((v) -> new FromValueResponse(v.from().toString(), v.value() == null ? "" : v.value())).toList()));
        return new SettingsResponse(
                settings.clerkLimit() == null ? null : settings.clerkLimit().toPlainString(),
                settings.floor().toPlainString(),
                settings.terms(),
                settings.gradeTerms(),
                settings.latePct().toPlainString(),
                settings.policyDate() == null ? "" : settings.policyDate().toString(),
                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
                settings.entryDate() == null ? "" : settings.entryDate().toString(),
                settings.cap() == null ? "" : settings.cap().toPlainString(),
                settings.proofThreshold() == null ? "" : settings.proofThreshold().toPlainString(),
                noteThreshold == null ? "" : noteThreshold.toPlainString(),
                reviewThreshold == null ? "" : reviewThreshold.toPlainString(),
                settings.roles().stream().map((r) -> new RoleResponse(r.user(), r.role().label())).toList(),
                history,
                settings.permissions().entries(),
                settings.graceDays() == null ? "" : settings.graceDays().toString(),
                settings.delegations().stream().map((d) -> new DelegationResponse(d.user(), d.from().toString(),
                        d.to().toString(), d.by())).toList(),
                settings.pot() == null ? "" : settings.pot().toPlainString(),
                settings.parent() == null ? "" : settings.parent(),
                Integer.toString(settings.fiscalStartMonth()),
                settings.alertThreshold() == null ? "" : settings.alertThreshold().toPlainString(),
                rounding == null ? "" : rounding,
                settings.escalateAfter() == null ? "" : settings.escalateAfter().toString(),
                settings.reviewSla() == null ? "" : settings.reviewSla().toString(),
                String.join(",", settings.proofKinds()),
                settings.defaultGrade() == null ? "" : settings.defaultGrade(),
                settings.scoreMid() == null ? "" : settings.scoreMid().toString(),
                settings.scoreHigh() == null ? "" : settings.scoreHigh().toString(),
                settings.scoreLog() ? "on" : "");
    }
